// === HAZARD SYSTEM =============================================================
const HAZARD_SPEED = 150; // px/sec vertical movement
const HAZARD_RADIUS = 8;
const SAFE_RADIUS = 200; // safe distance from player at spawn
const HAZARD_SPAWN_INTERVAL = 1.5; // base interval seconds
let hazardSpawnTimer = 0;

function spawnHazard() {
  // Random x position within canvas, respecting radius
  const x = Math.random() * (canvas.width - HAZARD_RADIUS * 2) + HAZARD_RADIUS;
  const y = -HAZARD_RADIUS; // spawn just above the visible area
  // Simple safe spawn check: ensure distance from player >= SAFE_RADIUS
  const dx = x - player.x;
  const dy = y - player.y;
  if (Math.hypot(dx, dy) < SAFE_RADIUS) {
    // Skip this spawn; will try again on next timer tick
    return;
  }
  hazards.push({ x, y, radius: HAZARD_RADIUS });
}

function updateHazards(dt) {
  // Spawn timer countdown
  hazardSpawnTimer -= dt;
  if (hazardSpawnTimer <= 0) {
    spawnHazard();
    // Reset timer with slight randomness
    hazardSpawnTimer = HAZARD_SPAWN_INTERVAL + Math.random();
  }
  // Move existing hazards
  for (let i = hazards.length - 1; i >= 0; i--) {
    const h = hazards[i];
    h.y += HAZARD_SPEED * dt;
    // Remove hazards that are off-screen
    if (h.y - h.radius > canvas.height) {
      hazards.splice(i, 1);
    }
  }
}

// === LOOP =============================================================

